begin;
-- Fase 6 — LC Content Standard 1.0: refactor pedagógico do módulo 2 de Lógica
update nexora.modules set description=$txt$Modele dados, tipos, operações e condições como partes verificáveis de uma regra, com prática de classificação, expressões e testes de fronteira.$txt$ where id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=2 limit 1);
update nexora.lessons set objective=$txt$Modelar o estado de um problema com variáveis que tenham significado claro, distinguindo o nome do dado, o valor atual e a responsabilidade que ele exerce na solução.$txt$,estimated_minutes=28,content=$json$[{"type":"story","title":"O pedido muda, mas o significado dos dados permanece","body":"Imagine um pedido em um aplicativo. O valor total começa em R$ 80 e passa para R$ 125 quando outro item é adicionado. A quantidade também muda. O cupom digitado e o status de pagamento podem mudar em momentos diferentes.\n\nO programa precisa acompanhar esse estado sem perder o significado de cada informação. Por isso não basta guardar valores: precisamos dar nomes estáveis para dados que mudam ao longo do processo."},{"type":"purpose","title":"Variáveis são parte da modelagem do problema","body":"Um nome bem escolhido ajuda a responder três perguntas: o que este dado representa, em qual domínio ele existe e quando pode mudar.\n\nSe você olha para `totalPedido`, `quantidadeItens` e `pagamentoAprovado` e consegue explicar o estado atual do pedido, já está usando variáveis como ferramenta de raciocínio — não apenas como sintaxe."},{"type":"concept","title":"Variável separa identidade e valor","body":"A variável possui uma identidade — o nome — e um valor atual. O valor pode mudar sem que a responsabilidade do nome mude. Se `quantidadeItens` passa de 2 para 3, ela continua representando a quantidade de itens.\n\nAlgoritmos trabalham com estados sucessivos. Cada atualização modifica o valor, mas o leitor precisa continuar entendendo o que está sendo acompanhado."},{"type":"comparison","title":"Nomes que carregam contexto reduzem ambiguidade","items":["`x = 349.90` obriga o leitor a descobrir o significado.","`valorPedido = 349.90` comunica o domínio imediatamente.","`valorPedidoEmCentavos` pode ser melhor quando a unidade precisa ficar explícita.","`status = true` é menos informativo que `pagamentoAprovado = true` quando existem vários estados."]},{"type":"guided_practice","title":"Modele um checkout antes de calcular","body":"Cenário: um cliente adicionou 3 itens, o total atual é R$ 349,90, digitou o cupom BEMVINDO10 e ainda não finalizou o pagamento.\n\nEscreva quatro nomes de variáveis para representar esse estado. Depois identifique qual muda quando um item é removido e qual muda quando o pagamento é confirmado. O objetivo é justificar por que cada nome reduz ambiguidade."},{"type":"professional_context","title":"Nomes também são comunicação de equipe","body":"Variáveis aparecem em código, testes, logs, métricas e revisões. Um nome ruim aumenta a chance de outra pessoa interpretar a regra de forma errada. Um nome claro reduz custo de manutenção e torna bugs mais fáceis de localizar."},{"type":"recap","items":["Variável representa um dado do problema em determinado momento.","O valor pode mudar sem alterar o significado da variável.","Nomes devem comunicar responsabilidade e, quando necessário, unidade.","Modelar os dados antes da regra reduz erros nas etapas seguintes."]}]$json$::jsonb,lab_type='data_model',lab_config=$json${"checkpoint":{"question":"Qual nome representa melhor o total atual de um pedido?","options":["x","numero","totalPedido","valor"],"answer":2,"feedback":"Correto. O nome comunica o papel do dado.","feedback_incorrect":"Prefira o nome que explique o dado mesmo fora da linha em que foi criado."},"data_model":{"scenario":"Classifique os elementos de um checkout antes de construir qualquer expressão.","options":["Dado mutável","Constante da regra","Entrada externa","Estado booleano"],"rows":[{"label":"valorPedido","value":"349.90","answer":0,"hint":"Pode mudar quando itens entram ou saem."},{"label":"LIMITE_DESCONTO","value":"300","answer":1,"hint":"Define uma regra estável durante a execução."},{"label":"cupomDigitado","value":"\"BEMVINDO10\"","answer":2,"hint":"Veio de fora do programa e precisa ser validado."},{"label":"pagamentoAprovado","value":"false","answer":3,"hint":"Representa um estado lógico."}],"feedback":"Modelo correto. Você separou estado, regra, entrada e condição antes de calcular.","feedback_incorrect":"Revise o papel de cada item: ele muda com o processo, define uma regra, chega de fora ou representa um estado lógico?"},"module":"Dados e expressões","editorial_version":"lc-content-standard-1.0","pedagogy":"competencia-aplicacao-validacao"}$json$::jsonb where module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=2 limit 1) and position=1;
update nexora.lessons set objective=$txt$Reconhecer valores que pertencem à regra e devem permanecer estáveis durante a execução, substituindo números mágicos por constantes nomeadas e justificáveis.$txt$,estimated_minutes=24,content=$json$[{"type":"concept","title":"Constante documenta uma decisão da regra","body":"Quando um algoritmo usa 300 como limite de desconto, esse número não é apenas um dado: ele expressa uma decisão de negócio. Se aparecer solto em várias fórmulas, a intenção fica escondida.\n\n`LIMITE_DESCONTO = 300` transforma o valor em linguagem do domínio e cria um ponto claro de manutenção."},{"type":"example","title":"O mesmo número pode ter significados diferentes","body":"`LIMITE_DESCONTO = 300`, `LIMITE_CREDITO = 300` e `ESTOQUE_MAXIMO = 300` usam o mesmo valor, mas representam regras diferentes. O nome é o que preserva o significado."},{"type":"mechanics","title":"Quando promover um valor a constante","items":["Quando representa limite, taxa, configuração ou política.","Quando aparece em mais de uma parte da mesma regra.","Quando uma mudança deveria ocorrer em um único ponto controlado.","Quando o número isolado não explica por que existe."]},{"type":"mistake","title":"Constante não significa valor eterno","body":"Uma taxa de 10% pode ser constante durante uma campanha e mudar no mês seguinte. O importante é que, durante a execução daquela versão da regra, o valor não varie como um dado operacional."},{"type":"guided","title":"Estado ou regra?","question":"Em um cálculo de comissão fixa de 5% sobre cada venda, qual dado tende a ser constante?","options":["valorVenda","nomeCliente","TAXA_COMISSAO","quantidadeVendida"],"answer":2,"feedback":"Correto. A taxa define a regra.","feedback_incorrect":"Procure o valor que define a política do cálculo, não o dado que muda em cada venda."},{"type":"recap","items":["Constantes tornam regras explícitas.","O nome explica por que o valor existe.","Centralizar limites e taxas reduz inconsistências.","Constante é estabilidade no contexto da regra, não eternidade."]}]$json$::jsonb,lab_type='data_model',lab_config=$json${"checkpoint":{"question":"Qual abordagem deixa explícito um limite de crédito de R$ 1.500?","options":["Usar 1500 em cada comparação.","Criar LIMITE_CREDITO = 1500.","Guardar 1500 em x.","Trocar 1500 em cada função."],"answer":1,"feedback":"Correto. A constante centraliza e nomeia a regra.","feedback_incorrect":"A melhor opção precisa explicar o significado de 1500."},"data_model":{"scenario":"Separe dados operacionais de valores que definem a regra.","options":["Dado mutável","Constante da regra","Entrada externa","Estado booleano"],"rows":[{"label":"valorVenda","value":"1280.00","answer":0},{"label":"TAXA_COMISSAO","value":"0.05","answer":1},{"label":"quantidadeItens","value":"4","answer":0},{"label":"LIMITE_CREDITO","value":"1500","answer":1}],"feedback":"Classificação correta. Você distinguiu estado e regra.","feedback_incorrect":"Pergunte se o valor muda a cada execução ou se define a política usada para avaliar essas execuções."},"module":"Dados e expressões","editorial_version":"lc-content-standard-1.0","pedagogy":"competencia-aplicacao-validacao"}$json$::jsonb where module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=2 limit 1) and position=2;
update nexora.lessons set objective=$txt$Distinguir números, textos, booleanos e entradas externas, identificando quando um dado precisa ser validado ou convertido antes de participar de operações.$txt$,estimated_minutes=30,content=$json$[{"type":"story","title":"A tela mostrou 18, mas o programa recebeu \"18\"","body":"Em interfaces web, dados digitados pelo usuário frequentemente chegam como texto. Na tela, 18 e \"18\" parecem quase iguais. Para o programa, porém, um é quantidade e o outro é sequência de caracteres.\n\nSe o texto for usado diretamente em um cálculo, o resultado pode ser erro, conversão automática inesperada ou concatenação."},{"type":"concept","title":"Tipo define quais operações fazem sentido","body":"Número representa quantidade e participa naturalmente de cálculos. Texto representa sequências e identificadores. Booleano representa estado lógico: verdadeiro ou falso.\n\nO tipo faz parte da modelagem: idade é quantidade; CPF é identificador textual; aceitação de termos é estado booleano."},{"type":"comparison","title":"Classifique pelo significado, não pela aparência","items":["Idade 18 → número.","CEP `45653-000` → texto.","Telefone `73999999999` → texto, apesar dos dígitos.","`aceitouTermos = true` → booleano.","Valor digitado em campo pode chegar como texto mesmo representando número."]},{"type":"example","title":"Conversão consciente é parte da validação","body":"Se `idadeDigitada = \"18\"`, primeiro verifique se o texto representa um número válido e então converta. Se o usuário digitar `dezoito`, a entrada deve ser tratada, não convertida silenciosamente para qualquer valor."},{"type":"guided_analysis","title":"Analise um cadastro misto","body":"Um cadastro recebe nome, CPF, idade, salário digitado e aceite dos termos. Classifique cada dado pelo tipo do domínio e indique quais provavelmente chegam como texto pela interface. Depois marque quais precisam de conversão antes de cálculos."},{"type":"guided","title":"Qual dado deve continuar como texto?","question":"Qual informação deve normalmente ser tratada como texto mesmo contendo apenas números?","options":["quantidadeItens","precoUnitario","CPF","mediaNotas"],"answer":2,"feedback":"Correto. CPF é identificador, não quantidade.","feedback_incorrect":"Pergunte se operações aritméticas com esse dado fariam sentido."},{"type":"professional_context","title":"APIs e bancos tornam o tipo ainda mais importante","body":"Frontend, API e banco precisam concordar sobre o significado dos dados. Validar tipos na fronteira evita que valores inválidos avancem para cálculos, persistência ou relatórios."},{"type":"recap","items":["Tipo representa a natureza do dado.","Dígitos não significam automaticamente número.","Entradas externas devem ser validadas antes da conversão.","Identificadores, quantidades e estados lógicos têm comportamentos diferentes."]}]$json$::jsonb,lab_type='data_model',lab_config=$json${"checkpoint":{"question":"Um formulário envia `\"149.90\"` e a aplicação precisa somar frete. O que deve acontecer primeiro?","options":["Concatenar o frete.","Validar e converter para número.","Transformar frete em booleano.","Remover o ponto decimal."],"answer":1,"feedback":"Correto. A operação exige um número válido.","feedback_incorrect":"O valor chegou como texto; valide o domínio antes do cálculo."},"data_model":{"scenario":"Classifique os dados pelo tipo que a aplicação deve usar.","options":["Número","Texto","Booleano","Texto a converter para número"],"rows":[{"label":"idade","value":"18","answer":0},{"label":"cpf","value":"\"12345678900\"","answer":1},{"label":"aceitouTermos","value":"true","answer":2},{"label":"salarioDigitado","value":"\"2500.00\"","answer":3}],"feedback":"Tipos corretos. Você diferenciou domínio, representação e conversão.","feedback_incorrect":"Revise se o dado é quantidade, identificador, estado lógico ou entrada textual que precisa virar quantidade."},"module":"Dados e expressões","editorial_version":"lc-content-standard-1.0","pedagogy":"competencia-aplicacao-validacao"}$json$::jsonb where module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=2 limit 1) and position=3;
update nexora.lessons set objective=$txt$Construir e validar expressões aritméticas com precedência, parênteses e decomposição em etapas, prevendo resultados antes de executar.$txt$,estimated_minutes=32,content=$json$[{"type":"purpose","title":"Uma fórmula precisa representar a regra na ordem correta","body":"Uma expressão pode conter os números certos e produzir resposta errada quando a ordem das operações não corresponde à intenção. Aprender operadores é aprender a traduzir uma regra em transformações verificáveis."},{"type":"concept","title":"Precedência resolve ambiguidades","body":"Multiplicação e divisão normalmente são avaliadas antes de soma e subtração. Por isso `nota1 + nota2 / 2` não representa a média. A forma correta agrupa a soma: `(nota1 + nota2) / 2`."},{"type":"mechanics","title":"Quebre cálculos maiores em resultados intermediários","items":["Calcule subtotal antes de desconto quando isso melhora a leitura.","Nomeie taxas e limites como constantes.","Use parênteses para refletir a regra.","Escolha casos simples cujo resultado você consegue prever mentalmente."]},{"type":"example","title":"Carrinho com subtotal, desconto e frete","body":"Para 3 itens de R$ 20, desconto final de R$ 5 e frete de R$ 12: subtotal = 60; após desconto = 55; total = 67. Separar etapas permite conferir cada transformação."},{"type":"example","title":"Percentual também é expressão","body":"15% de R$ 200 pode ser escrito como `200 * 15 / 100` ou `200 * 0.15`. Em ambos os casos, você deve conseguir prever 30 antes da execução."},{"type":"guided_practice","title":"Projete casos antes de confiar na fórmula","body":"Para média, teste valores iguais, um valor zero e dois valores diferentes. Para desconto, teste um caso simples e outro com casa decimal. Se você testa apenas um caso confortável, pode confirmar uma fórmula errada por coincidência."},{"type":"mistake","title":"Expressão curta não é necessariamente clara","body":"Quando a regra possui etapas conceituais — subtotal, desconto, frete, imposto — nomes intermediários podem ser melhores que uma única linha difícil de auditar."},{"type":"recap","items":["Precedência altera resultados.","Parênteses devem refletir a regra.","Resultados intermediários podem melhorar clareza.","Toda fórmula deve ser confrontada com valores previsíveis."]}]$json$::jsonb,lab_type='expression',lab_config=$json${"checkpoint":{"question":"Qual expressão calcula a média de 8 e 6 corretamente?","options":["8 + 6 / 2","(8 + 6) / 2","8 * 6 / 2","8 + (6 * 2)"],"answer":1,"feedback":"Correto. A soma precisa ocorrer antes da divisão.","feedback_incorrect":"Revise a precedência."},"expression":{"title":"Expression Lab — ordem das operações","scenario":"Uma escola calcula a média simples de duas notas.","instruction":"Teste mentalmente cada opção nos três cenários.","options":["nota1 + nota2 / 2","(nota1 + nota2) / 2","nota1 * nota2 / 2","(nota1 / 2) + nota2"],"answer":1,"cases":[{"input":"8 e 6","expected":"7"},{"input":"10 e 0","expected":"5"},{"input":"7 e 7","expected":"7"}],"feedback":"Expressão correta. O agrupamento preserva a média em todos os casos.","feedback_incorrect":"Essa expressão falha em pelo menos um caso. Siga a precedência real."},"module":"Dados e expressões","editorial_version":"lc-content-standard-1.0","pedagogy":"competencia-aplicacao-validacao"}$json$::jsonb where module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=2 limit 1) and position=4;
update nexora.lessons set objective=$txt$Representar regras de limite com comparações booleanas corretas e projetar testes de fronteira capazes de detectar erros de inclusão e exclusão.$txt$,estimated_minutes=28,content=$json$[{"type":"story","title":"O bug só aparece para quem tem exatamente 18 anos","body":"A regra diz “a partir de 18 anos”, mas a implementação usa `idade > 18`. Pessoas com 19 e 30 entram; quem tem exatamente 18 é rejeitado. O sistema parece correto até a fronteira ser testada."},{"type":"comparison","title":"Palavras da regra indicam operadores diferentes","items":["“mais de 18” → > 18.","“a partir de 18” → >= 18.","“menos de 500” → < 500.","“até 500, inclusive” → <= 500.","“exatamente 500” → == 500."]},{"type":"concept","title":"Comparação transforma uma relação em booleano","body":"`valor >= 300` devolve verdadeiro ou falso. A qualidade da comparação depende de representar exatamente a linguagem da regra."},{"type":"guided_analysis","title":"Use três casos para testar uma fronteira","body":"Crie um caso imediatamente abaixo, o próprio limite e um imediatamente acima. Para idade >= 18: 17 falso, 18 verdadeiro, 19 verdadeiro."},{"type":"mastery","title":"Você domina comparações quando consegue testar antes do código","items":["Identificar a fronteira textual.","Escolher operador inclusivo ou exclusivo.","Prever abaixo, no limite e acima.","Explicar por que igualdade ou diferença fazem sentido."]},{"type":"recap","items":["Comparações produzem booleanos.","Fronteiras inclusivas e exclusivas não são equivalentes.","Teste abaixo, no limite e acima.","A linguagem do requisito orienta o operador."]}]$json$::jsonb,lab_type='expression',lab_config=$json${"checkpoint":{"question":"Uma promoção vale para compras de R$ 300 ou mais. Qual expressão está correta?","options":["valor > 300","valor >= 300","valor < 300","valor == 0"],"answer":1,"feedback":"Correto. O limite está incluído.","feedback_incorrect":"A expressão precisa aceitar exatamente 300."},"expression":{"title":"Expression Lab — teste de fronteira","scenario":"Frete grátis para pedidos de R$ 300 ou mais.","instruction":"Use 299, 300 e 301 como prova da regra.","options":["valorPedido > 300","valorPedido >= 300","valorPedido <= 300","valorPedido == 300"],"answer":1,"cases":[{"input":"R$ 299","expected":"sem frete grátis"},{"input":"R$ 300","expected":"frete grátis"},{"input":"R$ 301","expected":"frete grátis"}],"feedback":"Fronteira correta: 300 é aceito e valores menores são recusados.","feedback_incorrect":"Teste o próprio limite; a regra precisa aceitar exatamente 300."},"module":"Dados e expressões","editorial_version":"lc-content-standard-1.0","pedagogy":"competencia-aplicacao-validacao"}$json$::jsonb where module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=2 limit 1) and position=5;
update nexora.lessons set objective=$txt$Combinar condições booleanas com E, OU e NÃO, tornando o agrupamento explícito e validando regras compostas com cenários que exercitem cada condição.$txt$,estimated_minutes=32,content=$json$[{"type":"story","title":"Condições corretas podem formar uma regra errada quando combinadas","body":"Um benefício exige cliente ativo E pelo menos 6 meses. Se a implementação usar OU, um recém-cadastrado ativo seria aprovado e um cliente antigo inativo também. O erro está na combinação lógica."},{"type":"concept","title":"Operadores lógicos combinam booleanos","body":"E exige todas as condições verdadeiras. OU exige pelo menos uma. NÃO inverte um booleano. A pergunta principal é semântica: simultaneidade, alternativa ou negação?"},{"type":"comparison","title":"Traduza a frase de negócio","items":["“Ativo E com 6 meses” → ambas obrigatórias.","“Pix OU cartão” → uma alternativa basta.","“NÃO bloqueado” → inverte o estado.","“(VIP OU compra alta) E ativo” exige agrupamento explícito."]},{"type":"example","title":"Benefício por tempo e status","body":"Com `clienteAtivo = true` e `mesesCadastro = 8`, a expressão `clienteAtivo && mesesCadastro >= 6` é verdadeira. Se qualquer uma das duas condições falhar, o resultado deve ser falso."},{"type":"guided","title":"Alternativas válidas","question":"Uma entrega pode ser retirada pelo titular OU por pessoa autorizada. Qual operador representa a regra?","options":["E","OU","NÃO","Igualdade"],"answer":1,"feedback":"Correto. Uma alternativa é suficiente.","feedback_incorrect":"A frase descreve possibilidades alternativas."},{"type":"mistake","title":"Misturar E e OU sem agrupamento é arriscado","body":"Quando a regra crescer, crie condições intermediárias: `temPerfilElegivel = vip || compraAlta`; depois `podeReceber = temPerfilElegivel && clienteAtivo`. Isso costuma ser mais auditável que uma expressão longa."},{"type":"professional_context","title":"Precisão lógica afeta negócio e segurança","body":"Autorização, crédito, descontos e segmentação dependem de regras compostas. Trocar E por OU pode deixar de ser um bug visual e virar falha de negócio ou acesso."},{"type":"recap","items":["E exige simultaneidade.","OU representa alternativas.","NÃO inverte um estado.","Agrupamentos e nomes intermediários tornam regras mais seguras."]}]$json$::jsonb,lab_type='expression',lab_config=$json${"checkpoint":{"question":"Um benefício exige cliente ativo E cadastro com pelo menos 6 meses. Qual cenário deve ser aprovado?","options":["Ativo e 8 meses","Ativo e 2 meses","Inativo e 12 meses","Inativo e 1 mês"],"answer":0,"feedback":"Correto. As duas condições são verdadeiras.","feedback_incorrect":"Com E, nenhuma condição pode falhar."},"expression":{"title":"Expression Lab — lógica composta","scenario":"O benefício só vale quando o cliente está ativo E possui pelo menos 6 meses.","instruction":"Confira casos em que apenas uma condição é verdadeira.","options":["clienteAtivo || mesesCadastro >= 6","clienteAtivo && mesesCadastro >= 6","!clienteAtivo && mesesCadastro >= 6","clienteAtivo && mesesCadastro < 6"],"answer":1,"cases":[{"input":"ativo=true, meses=8","expected":"concede"},{"input":"ativo=true, meses=2","expected":"não concede"},{"input":"ativo=false, meses=12","expected":"não concede"}],"feedback":"Regra correta. As duas exigências são simultâneas.","feedback_incorrect":"Essa expressão falha em pelo menos um cenário. Revise E e OU."},"module":"Dados e expressões","editorial_version":"lc-content-standard-1.0","pedagogy":"competencia-aplicacao-validacao"}$json$::jsonb where module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=2 limit 1) and position=6;
update nexora.lessons set objective=$txt$Compor uma regra completa a partir de dados, constantes, cálculos, comparações e operadores lógicos, decompondo a expressão em partes nomeadas e validando casos normais, limites e exceções.$txt$,estimated_minutes=36,content=$json$[{"type":"purpose","title":"Agora os conceitos precisam funcionar juntos","body":"Uma regra real mistura nomes, constantes, tipos, cálculos, comparações e lógica. O objetivo não é criar a maior expressão possível, mas uma solução que outra pessoa consiga ler, testar e modificar."},{"type":"guided_analysis","title":"Comece decompondo o requisito","body":"Regra: clientes ativos recebem 10% de desconto quando a compra é de R$ 300 ou mais. Identifique dados mutáveis, constantes, a comparação de limite e a combinação lógica com o estado do cliente."},{"type":"mechanics","title":"Construa em camadas observáveis","items":["Defina dados e constantes.","Valide tipos de entradas externas.","Calcule valores intermediários.","Crie cada comparação separadamente.","Combine booleanos depois.","Teste casos normais, fronteiras e exceções."]},{"type":"example","title":"De requisito para variáveis intermediárias","body":"`atingiuMinimo = valorCompra >= LIMITE_DESCONTO`\n`elegivel = clienteAtivo && atingiuMinimo`\n`desconto = elegivel ? valorCompra * TAXA_DESCONTO : 0`\n`totalFinal = valorCompra - desconto`\n\nA decomposição permite verificar cada parte."},{"type":"comparison","title":"Uma linha gigante × etapas nomeadas","items":["Expressão única pode esconder precedência.","Booleanos intermediários documentam perguntas da regra.","Resultados intermediários facilitam testes e logs.","Nomes extras são úteis quando reduzem a carga de raciocínio."]},{"type":"guided_practice","title":"Projete uma matriz mínima de testes","body":"Teste: ativo com R$ 299; ativo com R$ 300; ativo com R$ 500; inativo com R$ 500; entrada inválida para valor. Escreva primeiro o resultado esperado e só depois confronte com a expressão."},{"type":"mistake","title":"Um caso feliz não prova a solução","body":"Se você testa apenas cliente ativo com R$ 500, várias expressões erradas também retornam desconto. O limite de R$ 300 e o cliente inativo são casos que realmente diferenciam implementações."},{"type":"mastery","title":"Sinal de domínio do módulo","items":["Justificar nomes e tipos.","Identificar constantes.","Prever cálculos e booleanos.","Criar casos de fronteira.","Refatorar expressão difícil em etapas nomeadas."]},{"type":"recap","items":["Expressões completas são composições de conceitos menores.","Decomposição melhora teste e manutenção.","Fronteiras e isolamento de condições revelam bugs.","Clareza é mais valiosa que brevidade isolada."]}]$json$::jsonb,lab_type='expression',lab_config=$json${"checkpoint":{"question":"Qual estratégia torna uma regra complexa mais verificável?","options":["Escrever tudo em uma linha.","Separar cálculos e condições em partes nomeadas e testar cada uma.","Remover parênteses.","Trocar nomes por letras."],"answer":1,"feedback":"Correto. A decomposição torna intenção e falhas visíveis.","feedback_incorrect":"Prefira a estratégia que permita validar cada parte."},"expression":{"title":"Expression Lab — regra integrada","scenario":"Clientes ativos recebem desconto quando a compra é de R$ 300 ou mais.","instruction":"Escolha a condição que respeita simultaneidade e fronteira.","options":["clienteAtivo || valorCompra >= LIMITE_DESCONTO","clienteAtivo && valorCompra >= LIMITE_DESCONTO","clienteAtivo && valorCompra > LIMITE_DESCONTO","!clienteAtivo && valorCompra >= LIMITE_DESCONTO"],"answer":1,"cases":[{"input":"ativo=true, valor=299","expected":"sem desconto"},{"input":"ativo=true, valor=300","expected":"com desconto"},{"input":"ativo=false, valor=500","expected":"sem desconto"},{"input":"ativo=true, valor=500","expected":"com desconto"}],"feedback":"Regra integrada correta. A condição respeita simultaneidade e fronteira.","feedback_incorrect":"Revise R$ 300 e cliente inativo; eles distinguem as alternativas."},"module":"Dados e expressões","editorial_version":"lc-content-standard-1.0","pedagogy":"competencia-aplicacao-validacao"}$json$::jsonb where module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=2 limit 1) and position=7;
