update nexora.questions set prompt=$txt$Uma expressão mistura E e OU e ficou difícil de explicar. Qual refatoração é mais adequada?$txt$,question_type='multiple_choice',options=$json$[{"id":"a","label":"Remover parênteses."},{"id":"b","label":"Criar booleanos intermediários com nomes do domínio e depois combiná-los."},{"id":"c","label":"Trocar tudo por OU."},{"id":"d","label":"Usar números no lugar de booleanos."}]$json$::jsonb,correct_answer=$json${"option_id":"b"}$json$::jsonb,feedback_correct=$txt$Correto. Nomes intermediários tornam intenção e agrupamento auditáveis.$txt$,feedback_incorrect=$txt$Prefira a solução que reduza a carga de raciocínio.$txt$,difficulty=3 where assessment_id=(select a.id from nexora.assessments a where a.module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=2 limit 1) order by a.created_at asc limit 1) and position=10;
