update nexora.assessments set title='Checkpoint aplicado — Dados, tipos e expressões',pass_score=70,max_attempts=3 where id=(select a.id from nexora.assessments a where a.module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=2 limit 1) order by a.created_at asc limit 1);
update nexora.learning_resources set title=$txt$Apostila LC — Dados, tipos e expressões$txt$,resource_type='guide',summary=$txt$Material integrado do módulo com modelagem de dados, tipos, cálculos, comparações, lógica e roteiro de validação.$txt$,content=$json${"editorial_version":"lc-content-standard-1.0","sections":[{"title":"Modelar antes de calcular","body":"Defina quais dados mudam, quais valores pertencem à regra e quais entradas precisam de validação."},{"title":"Tipo é significado","body":"Números representam quantidades; textos representam sequências e identificadores; booleanos representam estados lógicos."},{"title":"Expressões aritméticas","body":"Use precedência conscientemente, parênteses quando refletem agrupamento e resultados intermediários quando melhoram a leitura."},{"title":"Comparações e fronteiras","body":"Requisitos com mínimo, máximo, a partir de, até e inclusive devem ser testados abaixo, no limite e acima."},{"title":"Lógica composta","body":"E exige simultaneidade, OU representa alternativas e NÃO inverte o estado."},{"title":"Checklist de validação","items":["Consigo explicar cada variável?","Cada constante tem significado?","Entradas externas são validadas?","A expressão funciona nos limites?","Consigo prever três casos antes de executar?"]}]}$json$::jsonb,status='published' where module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=2 limit 1) and position=1;
