update nexora.learning_resources set title=$txt$Guia de depuração de expressões$txt$,resource_type='guide',summary=$txt$Procedimento curto para localizar erros de tipo, precedência, fronteira e lógica composta.$txt$,content=$json${"editorial_version":"lc-content-standard-1.0","sections":[{"title":"1. Confira os dados","items":["O valor possui o tipo esperado?","Alguma entrada precisava de conversão?","A unidade está clara?"]},{"title":"2. Isole o cálculo","items":["Quebre a fórmula em etapas.","Preveja um caso simples.","Confira precedência e parênteses."]},{"title":"3. Isole as condições","items":["Teste cada comparação.","Teste a fronteira.","Depois combine E, OU e NÃO."]},{"title":"4. Compare esperado × observado","body":"Um bug é mais fácil de localizar quando você sabe qual resultado deveria aparecer em cada etapa."}]}$json$::jsonb,status='published' where module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=2 limit 1) and position=2;
