update nexora.learning_resources set title=$txt$Oficina — Regra de desconto verificável$txt$,resource_type='exercise',summary=$txt$Atividade prática para modelar uma regra completa e provar seu comportamento com uma matriz de testes.$txt$,content=$json${"editorial_version":"lc-content-standard-1.0","sections":[{"title":"Cenário","body":"Clientes ativos recebem 10% de desconto quando a compra é de R$ 300 ou mais."},{"title":"Entregável","items":["Liste variáveis e constantes.","Defina tipos esperados.","Escreva a condição.","Calcule desconto e total final.","Crie cinco casos de teste."]},{"title":"Casos obrigatórios","items":["Ativo com R$ 299.","Ativo com R$ 300.","Ativo com R$ 500.","Inativo com R$ 500.","Valor em formato inválido."]},{"title":"Critério","body":"Outra pessoa deve conseguir reproduzir sua lógica e justificar cada resultado."}]}$json$::jsonb,status='published' where module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=2 limit 1) and position=3;
