update nexora.learning_resources set title=$txt$Caderno de casos — Dados e expressões$txt$,resource_type='exercise',summary=$txt$Cinco situações curtas para praticar modelagem, tipos, fronteiras e lógica sem repetir o exemplo da aula.$txt$,content=$json${"editorial_version":"lc-content-standard-1.0","sections":[{"title":"Caso 1 — Frete","body":"Frete grátis a partir de R$ 200. Modele constante, comparação e três testes de fronteira."},{"title":"Caso 2 — Idade","body":"Cadastro a partir de 16 anos com autorização e a partir de 18 sem autorização. Decomponha as condições."},{"title":"Caso 3 — Estoque","body":"Calcule valor total com quantidade e preço unitário, tratando quantidade zero."},{"title":"Caso 4 — Login","body":"Acesso exige usuário ativo e senha válida; conta bloqueada deve ser recusada."},{"title":"Caso 5 — Formulário","body":"Preço chega como texto, CPF como texto e aceite como booleano. Classifique e descreva conversões."}]}$json$::jsonb,status='published' where module_id=(select m.id from nexora.modules m join nexora.courses c on c.id=m.course_id where c.slug='logica-programacao-basica' and m.position=2 limit 1) and position=4;
